style.css:
@-moz-document domain("roblox.com") {
:root {
    --theme-color: /*[[bH7eY]]*/;
}

/* Global */
[class*="btn-growth"], [class*="bg-action-emphasis"], [class*="play-game"], [class*="PurchaseButton"], [class*="cart-number-container"], .web-blox-css-tss-1ul2oes-DialogActions-root > [class*="Button-contained"]:not(.Mui-disabled), [class*="btn-toggle on"], #user-profile-header-AddFriend, #user-profile-header-AcceptFriendRequest, .Mui-checked .MuiSwitch-thumb, .Mui-checked + .MuiSwitch-track, .apply-button {
    background-color: var(--theme-color) !important;
    border: none !important;
    color: white !important
}

[class*="MuiSlider-track"], [class*="MuiSlider-thumb"], [class*="Mui-checked"], .MuiFormHelperText-root > .web-blox-css-tss-v85u72-Link-colorPrimary-Link-root, .web-blox-css-tss-s1kbrk-Link-colorPrimary-Link-root-experienceTitle, .web-blox-css-tss-18zgpl3-Button-text {
    color: var(--theme-color) !important;
}

.screentime-chart-container .highcharts-column-series path.highcharts-point, .web-blox-css-mui-1cw4hi4 {
    fill: var(--theme-color) !important;
}

/* Chat bubbles */
.dialog-message-container:not(.message-inbound) .dialog-message {
    background-color: var(--theme-color) !important;
    border-color: var(--theme-color) !important;
}

.dialog-triangle.trusted-comms:before, .dialog-triangle.trusted-comms:after,
.dialog-message:before, .dialog-message:after {
    border-left-color: var(--theme-color) !important;
}

.icon-radio-check-circle-filled {
    border-color: var(--theme-color) !important;
}
}
